10	/**
11	 * Flags a soft duplicate. A new owner that reaches this step was not rejected by the identity
12	 * check ({@link EnsureUniqueIdentity}) — no live owner repeats its {@link Owner#getIdentityKey()
13	 * identity key}. A declared member ({@code sharesHousehold}) is a genuine household member, not a
14	 * suspected duplicate, so it is never flagged here. Any other owner that shares an existing live
15	 * owner's postcode and a phonetically-equal last name ({@link Identities}) while differing in
16	 * identity key is created anyway and marked as a possible duplicate of that owner. Runs before
17	 * {@link SaveOwner} persists the flags; when several match, the earliest (lowest id) is recorded.
18	 * An owner with no postcode can never be a possible duplicate.
19	 */
20	public class AssignOwnerPossibleDuplicate {
21	
22	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
23	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            return;
25	        }
26	        Identities.softMatchesOf(ownerRepository, owner).stream()
27	                .min(Comparator.comparingInt(Owner::getId))
28	                .ifPresent(match -> {
29	                    owner.setPossibleDuplicate(true);
30	                    owner.setPossibleDuplicateOf(match.getId());
31	                });
32	    }
33	}
