1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	
6	/**
7	 * The fixed blocklist of disposable email domains that owner registrations are not
8	 * allowed to use. Kept separate from the syntactic email check so the two concerns
9	 * stay independent and reusable.
10	 */
11	public final class DisposableEmailDomains {
12	
13	    /** Domains known to hand out throwaway inboxes. */
14	    private static final Set<String> BLOCKED = Set.of(
15	            "mailinator.com", "tempmail.com", "guerrillamail.com");
16	
17	    private DisposableEmailDomains() {
18	    }
19	
20	    /**
21	     * Whether an email address's domain is on the disposable-domain blocklist. Matching
22	     * is case-insensitive; an address with no '@' or no domain is not blocked (its
23	     * syntax is the concern of the email format check).
24	     *
25	     * @param email the candidate email address
26	     * @return {@code true} when the domain after the last '@' is blocked
27	     */
28	    public static boolean isBlocked(String email) {
29	        if (email == null) {
30	            return false;
31	        }
32	        int at = email.lastIndexOf('@');
33	        if (at < 0 || at == email.length() - 1) {
34	            return false;
35	        }
36	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
37	        return BLOCKED.contains(domain);
38	    }
39	}
