1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.util.Soundex;
8	
9	/**
10	 * Shared identity logic for the create-owner pipeline. An owner's {@link Owner#getIdentityKey()
11	 * identity key} is the single fingerprint duplicate detection keys off: a hard duplicate repeats
12	 * an existing owner's key exactly, while a soft match sounds like an existing owner at the same
13	 * postcode without repeating the key. Both queries exclude soft-deleted owners, so a deleted
14	 * owner neither blocks nor flags a new one.
15	 */
16	final class Identities {
17	
18	    private Identities() {
19	    }
20	
21	    /**
22	     * The existing live owners whose {@link Owner#getIdentityKey() identity key} equals the
23	     * given owner's — the hard duplicates it repeats. Because the telephone is part of the key,
24	     * a match must share the telephone, so candidates are fetched by telephone and then compared
25	     * on the full key.
26	     */
27	    static List<Owner> duplicatesOf(OwnerRepository ownerRepository, Owner owner) {
28	        String identityKey = owner.getIdentityKey();
29	        return ownerRepository.findByTelephone(owner.getTelephone()).stream()
30	                .filter(existing -> !existing.isDeleted())
31	                .filter(existing -> identityKey.equals(existing.getIdentityKey()))
32	                .toList();
33	    }
34	
35	    /**
36	     * The existing live owners that soft-match the given owner: same postcode and a
37	     * phonetically-equal last name ({@link Soundex}) but a different {@link Owner#getIdentityKey()
38	     * identity key}. Empty when the owner has no postcode, since a postcode match is required.
39	     */
40	    static List<Owner> softMatchesOf(OwnerRepository ownerRepository, Owner owner) {
41	        String postcode = owner.getPostcode();
42	        if (postcode == null || postcode.isBlank()) {
43	            return List.of();
44	        }
45	        String soundex = Soundex.of(owner.getLastName());
46	        String identityKey = owner.getIdentityKey();
47	        return ownerRepository.findAll().stream()
48	                .filter(existing -> !existing.isDeleted())
49	                .filter(existing -> postcode.equals(existing.getPostcode()))
50	                .filter(existing -> soundex.equals(Soundex.of(existing.getLastName())))
51	                .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
52	                .toList();
53	    }
54	}
