156	    }
157	
158	    /**
159	     * The optional second line of the owner's structured address, in normalized form, or null
160	     * when absent or when the owner was created from the flat {@link #getAddress() address}.
161	     */
162	    public String getAddressLine2() {
163	        return this.addressLine2;
164	    }
165	
166	    public void setAddressLine2(String addressLine2) {
167	        this.addressLine2 = addressLine2;
168	    }
169	
170	    public String getCity() {
171	        return this.city;
172	    }
173	
174	    public void setCity(String city) {
175	        this.city = city;
176	    }
177	
178	    public String getTelephone() {
179	        return this.telephone;
180	    }
181	
182	    public void setTelephone(String telephone) {
183	        this.telephone = telephone;
184	    }
185	
186	    /**
187	     * The stored E.164 telephone formatted for humans: the country code, a space, then the
188	     * national digits grouped in threes (e.g. {@code "+61 412 345 678"}), while
189	     * {@link #getTelephone()} keeps the raw E.164 form. Derived from stored state, never
190	     * persisted.
191	     */
192	    public String getTelephoneDisplay() {
193	        return E164PhoneNumber.toDisplay(this.telephone);
194	    }
195	
196	    public String getEmail() {
197	        return this.email;
198	    }
199	
200	    public void setEmail(String email) {
201	        this.email = email;
202	    }
203	
204	    /**
205	     * The owner's postcode: a 4-digit code that, when supplied at creation, is validated
206	     * against the city's region and then stored verbatim. Optional, so may be null.
207	     */
208	    public String getPostcode() {
209	        return this.postcode;
210	    }
211	
212	    public void setPostcode(String postcode) {
213	        this.postcode = postcode;
214	    }
215	
216	    public LocalDate getRegistrationDate() {
217	        return this.registrationDate;
218	    }
219	
220	    public void setRegistrationDate(LocalDate registrationDate) {
221	        this.registrationDate = registrationDate;
222	    }
223	
224	    /**
225	     * The owner's date of birth. Optional, so may be null.
226	     */
227	    public LocalDate getBirthDate() {
228	        return this.birthDate;
229	    }
230	
231	    public void setBirthDate(LocalDate birthDate) {
232	        this.birthDate = birthDate;
233	    }
234	
235	    /**
236	     * The owner's age band as at registration: {@code "MINOR"} for under 18,
237	     * {@code "ADULT"} for 18 to 64, or {@code "SENIOR"} for 65 and over, measured from the
238	     * birth date against the registration date. Null when no birth date is recorded.
239	     * Derived from stored state, never persisted.
240	     */
241	    public String getAgeBand() {
242	        if (this.birthDate == null || this.registrationDate == null) {
243	            return null;
244	        }
245	        return AgeBand.of(this.birthDate, this.registrationDate);
246	    }
247	
248	    /**
249	     * The owner's member-id, formatted {@code <REGION><FY><HASH8><CHK>}: the canonical region,
250	     * the two-digit fiscal year of the registration date, the first eight upper-case hex
251	     * characters of the SHA-256 of the normalized telephone concatenated with the last name,
252	     * and a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (e.g.
253	     * {@code NSW261A2B3C4D7}). Assigned at creation.
254	     */
255	    public String getMemberId() {
256	        return this.memberId;
257	    }
258	
259	    public void setMemberId(String memberId) {
260	        this.memberId = memberId;
261	    }
262	
263	    /**
264	     * The owner's current primary identifier: the {@link #getMemberId() member-id}. The single
265	     * source of truth for "which field identifies this owner", so a consumer such as the
266	     * {@code OWNER_CREATED} audit event always carries the right value. Derived from stored
267	     * state, never persisted.
268	     */
269	    public String getPrimaryIdentifier() {
270	        return this.memberId;
271	    }
272	
273	    /**
274	     * The stable identifier of the household this owner belongs to: the first twelve hex
275	     * characters of the SHA-256 of the normalized last name and postcode, so every owner
276	     * sharing a last name and postcode resolves to the same value. Null when the owner has
277	     * no postcode. Assigned at creation.
278	     */
279	    public String getHouseholdId() {
280	        return this.householdId;
281	    }
282	
283	    public void setHouseholdId(String householdId) {
284	        this.householdId = householdId;
285	    }
286	
287	    public Integer getNamesakeCount() {
288	        return this.namesakeCount;
289	    }
290	
291	    public void setNamesakeCount(Integer namesakeCount) {
292	        this.namesakeCount = namesakeCount;
293	    }
294	
295	    public Integer getHouseholdSize() {
296	        return this.householdSize;
297	    }
298	
299	    public void setHouseholdSize(Integer householdSize) {
300	        this.householdSize = householdSize;
301	    }
302	
303	    /**
304	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: at
305	     * creation a new owner's level cannot exceed one above the highest level then held by an
306	     * existing member of its household (same last name and postcode). Null when no cap
307	     * applies, i.e. the household had no existing members. Captured at creation.
308	     */
309	    public Integer getMembershipLevelCap() {
310	        return this.membershipLevelCap;
311	    }
312	
313	    public void setMembershipLevelCap(Integer membershipLevelCap) {
314	        this.membershipLevelCap = membershipLevelCap;
315	    }
316	
317	    /**
318	     * Whether this owner was created as part of a bulk signup: {@code true} when more
319	     * than 80 owners had already been registered on this owner's registration date at
320	     * the moment it was created, {@code false} otherwise. Captured at creation.
321	     */
322	    public boolean isBulkSignupWarning() {
323	        return this.bulkSignupWarning;
324	    }
325	
326	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
327	        this.bulkSignupWarning = bulkSignupWarning;
328	    }
329	
330	    /**
331	     * Whether this owner's city was approaching its capacity limit when this owner was
332	     * created: {@code true} when the city already held between 40 and 49 owners (the hard
333	     * limit being 50), {@code false} otherwise. Captured at creation.
334	     */
335	    public boolean isCapacityWarning() {
336	        return this.capacityWarning;
337	    }
338	
339	    public void setCapacityWarning(boolean capacityWarning) {
340	        this.capacityWarning = capacityWarning;
341	    }
342	
343	    /**
344	     * Whether this owner resembles an existing one: {@code true} when, at creation, it shared
345	     * an existing owner's postcode and a phonetically-equal last name ({@link Soundex Soundex})
346	     * yet differed in {@link #getIdentityKey() identity key} and was not a declared household
347	     * member, {@code false} otherwise. A declared member (created with {@code sharesHousehold})
348	     * is a genuine member, not a suspected duplicate. When true, {@link #getPossibleDuplicateOf()}
349	     * holds that owner's id. Captured at creation.
350	     */
351	    public boolean isPossibleDuplicate() {
352	        return this.possibleDuplicate;
353	    }
354	
355	    public void setPossibleDuplicate(boolean possibleDuplicate) {
356	        this.possibleDuplicate = possibleDuplicate;
357	    }
358	
359	    /**
360	     * The id of the existing owner this owner possibly duplicates (same postcode and a
361	     * phonetically-equal last name but a different {@link #getIdentityKey() identity key}), or
362	     * null when it is not a possible duplicate. Captured at creation.
363	     */
364	    public Integer getPossibleDuplicateOf() {
365	        return this.possibleDuplicateOf;
366	    }
367	
368	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
369	        this.possibleDuplicateOf = possibleDuplicateOf;
370	    }
371	
372	    /**
373	     * Whether this owner has been soft-deleted: {@code true} once a {@code DELETE} has
374	     * flagged the record (which is retained rather than removed), {@code false} for a live
375	     * owner. A newly created owner is not deleted. A deleted owner is still returned by
376	     * {@code GET}, but is ignored by the create endpoint's duplicate and identity checks.
377	     */
378	    public boolean isDeleted() {
379	        return this.deleted;
380	    }
381	
382	    public void setDeleted(boolean deleted) {
383	        this.deleted = deleted;
384	    }
385	
386	    /**
387	     * The owner's locality: the canonical region carried in the {@code <REGION><FY><HASH8><CHK>}
388	     * member-id, i.e. the same region-and-hash identity used everywhere else. That region was
389	     * derived at creation by preferring the postcode range (NSW 2000-2099, VIC 3000-3099,
390	     * QLD 4000-4099), falling back to the fixed city-to-region table (Sydney->NSW,
391	     * Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no known range, or
392	     * {@code "UNKNOWN"} otherwise. For an owner with no member-id the region is derived directly
393	     * from the stored postcode and city. Derived from stored state, never persisted.
394	     */
395	    public String getLocality() {
396	        String region = MemberId.regionOf(this.memberId);
397	        return region != null ? region : CityLocality.forPostcodeOrCity(this.postcode, this.city);
398	    }
399	
400	    /**
401	     * The owner's market segment, formatted {@code <TIER>_<AREA>}: the tier is
402	     * {@code PREMIUM} when {@link #getMembershipLevel() membership level} is 3 or more,
403	     * otherwise {@code STANDARD}; the area is {@code METRO} when {@link #getLocality()
404	     * locality} is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}. One of
405	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
406	     * {@code STANDARD_REGIONAL}. Derived from stored state, never persisted.
407	     */
408	    public String getOwnerSegment() {
409	        return OwnerSegment.of(getMembershipLevel(), getLocality());
410	    }
411	
412	    /**
413	     * The owner's timezone: the IANA name for this owner's {@link #getLocality() locality}
414	     * via the fixed region-to-timezone table (NSW->Australia/Sydney,
415	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane), or {@code null} when the region
416	     * has no known timezone. Derived from stored state, never persisted.
417	     */
418	    public String getTimezone() {
419	        return RegionTimezone.forRegion(getLocality());
420	    }
421	
422	    /**
423	     * The owner's membership points, from 0 upwards: starts at 0, gains 2 when this owner
424	     * has an email address, gains 1 when this owner had no namesakes at creation
425	     * ({@code namesakeCount} is 0), gains 2 when this owner's household has 3 or more
426	     * members, and gains 3 once this owner's tenure spans at least one elapsed fiscal year.
427	     * A newly created owner has zero tenure, so it never earns those points at creation.
428	     * Derived from stored state, never persisted.
429	     */
430	    public int getMembershipPoints() {
431	        int points = 0;
432	        if (hasEmail()) {
433	            points += 2;
434	        }
435	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
436	            points += 1;
437	        }
438	        if (this.householdSize != null && this.householdSize >= 3) {
439	            points += 2;
440	        }
441	        if (getTenureFiscalYears() >= 1) {
442	            points += 3;
443	        }
444	        return points;
445	    }
446	
447	    /**
448	     * The owner's fiscal year: the {@code FY<YY>} label (fiscal year starting 1 July,
449	     * identified by its ending calendar year) of the {@code registrationDate}, or
450	     * {@code null} when no registration date is recorded. Derived from stored state, never
451	     * persisted.
452	     */
453	    public String getFiscalYear() {
454	        return this.registrationDate == null ? null : FiscalYear.labelOf(this.registrationDate);
455	    }
456	
457	    /**
458	     * The owner's membership level, from 1 to 4: derived from {@link #getMembershipPoints()}
459	     * as level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more, then capped at
460	     * the {@link #getMembershipLevelCap() membership level cap} when one applies. Derived from
461	     * stored state, never persisted.
462	     */
463	    public int getMembershipLevel() {
464	        int level = uncappedMembershipLevel();
465	        return this.membershipLevelCap == null ? level : Math.min(level, this.membershipLevelCap);
466	    }
467	
468	    private int uncappedMembershipLevel() {
469	        int points = getMembershipPoints();
470	        if (points <= 1) {
471	            return 1;
472	        }
473	        if (points <= 3) {
474	            return 2;
475	        }
476	        if (points <= 5) {
477	            return 3;
478	        }
479	        return 4;
480	    }
481	
482	    /**
483	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each
484	     * starting 1 July) between the {@code registrationDate} and the current server date, or
485	     * 0 when no registration date is recorded. Never negative in practice, since a future
486	     * registration date is rejected at creation.
487	     */
488	    private int getTenureFiscalYears() {
489	        if (this.registrationDate == null) {
490	            return 0;
491	        }
492	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
493	    }
494	
495	    /**
496	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
497	     * present, otherwise {@code "PHONE"}. Derived from stored state, never persisted.
498	     */
499	    public String getContactPreference() {
500	        return hasEmail() ? "EMAIL" : "PHONE";
501	    }
502	
503	    /**
504	     * The owner's identity key: the 64-character lower-case SHA-256 hex of the normalized
505	     * telephone, the lower-cased email (or empty when absent) and the {@link Soundex Soundex}
506	     * code of the last name, joined by {@code '|'}. Two owners collide on this key only when
507	     * they share a telephone, an email and a phonetically-equal surname, so it is the single
508	     * fingerprint the create endpoint's duplicate check keys off. Derived from stored state,
509	     * never persisted.
510	     */
511	    public String getIdentityKey() {
512	        String telephonePart = this.telephone == null ? "" : this.telephone;
513	        String emailPart = hasEmail() ? this.email.toLowerCase(Locale.ROOT) : "";
514	        String namePart = Soundex.of(getLastName());
515	        return Sha256.lowerHex(telephonePart + "|" + emailPart + "|" + namePart);
516	    }
517	
518	    private boolean hasEmail() {
519	        return this.email != null && !this.email.isEmpty();
520	    }
521	
522	    protected Set<Pet> getPetsInternal() {
523	        if (this.pets == null) {
524	            this.pets = new HashSet<>();
525	        }
526	        return this.pets;
527	    }
528	
529	    protected void setPetsInternal(Set<Pet> pets) {
530	        this.pets = pets;
531	    }
532	
533	    public List<Pet> getPets() {
534	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
535	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
536	        return Collections.unmodifiableList(sortedPets);
537	    }
538	
539	    public void setPets(List<Pet> pets) {
540	        this.pets = new HashSet<>(pets);
541	    }
542	
543	    public void addPet(Pet pet) {
544	        getPetsInternal().add(pet);
545	        pet.setOwner(this);
546	    }
547	
548	    /**
549	     * Return the Pet with the given name, or null if none found for this Owner.
550	     *
551	     * @param name to test
552	     * @return true if pet name is already in use
553	     */
554	    public Pet getPet(String name) {
555	        return getPet(name, false);
556	    }
557	
558	    /**
559	     * Return the Pet with the given name, or null if none found for this Owner.
560	     *
561	     * @param name to test
562	     * @return true if pet name is already in use
563	     */
564	    public Pet getPet(String name, boolean ignoreNew) {
565	        name = name.toLowerCase();
566	        for (Pet pet : getPetsInternal()) {
567	            if (!ignoreNew || !pet.isNew()) {
568	                String compName = pet.getName();
569	                compName = compName.toLowerCase();
570	                if (compName.equals(name)) {
571	                    return pet;
572	                }
573	            }
574	        }
575	        return null;
576	    }
577	
578	    public Pet getPet(Integer petId) {
579	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
580	    }
581	
582	    @Override
583	    public String toString() {
584	        return new ToStringCreator(this)
585	
586	            .append("id", this.getId())
587	            .append("new", this.isNew())
588	            .append("lastName", this.getLastName())
589	            .append("firstName", this.getFirstName())
590	            .append("address", this.address)
591	            .append("city", this.city)
592	            .append("telephone", this.telephone)
593	            .toString();
594	    }
595	}
